package io.knowledgebrain.planning;
import java.time.*;import java.util.*;import java.util.concurrent.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.postgresql.ds.PGSimpleDataSource;import org.flywaydb.core.Flyway;import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.server.ResponseStatusException;
import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_PLANNING_DATABASE_URL",matches=".+")
class ReminderStoreIntegrationTest {
    PGSimpleDataSource ds;JdbcTemplate sql;ScheduleStore schedules;ReminderStore store;String schema;
    final UuidV7 ids=new UuidV7(Clock.systemUTC());UUID space,actor;final String trace="b".repeat(32);
    @BeforeEach void init(){ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_PLANNING_DATABASE_URL"));ds.setUser("brain_planning");ds.setPassword(System.getenv("BRAIN_TEST_PLANNING_DATABASE_PASSWORD"));schema="reminder_test_"+UUID.randomUUID().toString().replace("-","");new JdbcTemplate(ds).execute("CREATE SCHEMA "+schema);ds.setCurrentSchema(schema);Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();sql=new JdbcTemplate(ds);schedules=new ScheduleStore(ds,Clock.systemUTC());store=new ReminderStore(ds,Clock.systemUTC());space=ids.next();actor=ids.next();}
    @AfterEach void cleanup(){sql.execute("DROP SCHEMA "+schema+" CASCADE");}
    String key(){return UUID.randomUUID().toString().replace("-","");}
    ScheduleStore.Schedule schedule(UUID space){return schedules.create(space,actor,key(),new ScheduleStore.Input("Original <script>","","2028-11-05T06:10:00Z","2028-11-05T07:10:00Z","America/New_York",null),trace).schedule();}
    ReminderRules.Input input(ScheduleStore.Schedule s,int minutes){return new ReminderRules.Input(s.scheduleId(),s.version(),minutes);}
    ReminderStore.Reminder create(ScheduleStore.Schedule s,int minutes){var i=input(s,minutes);return store.create(space,actor,key(),i,store.preview(space,i).previewHash(),trace).reminder();}
    void status(int code,Runnable fn){assertEquals(code,assertThrows(ResponseStatusException.class,fn::run).getStatusCode().value());}
    int count(String table){return sql.queryForObject("SELECT count(*) FROM "+table,Integer.class);}

    @Test void originalCreationAndImmutablePinsSurviveSourceMovesRetirementAndAccountClaim(){var s=schedule(space);var i=input(s,20);var p=store.preview(space,i);var key=key();var first=store.create(space,actor,key,i,p.previewHash(),trace);assertFalse(first.replay());var v=first.reminder();assertEquals("2028-11-05T05:50:00Z",v.remindsAt());assertEquals(s,schedules.get(space,s.scheduleId()));var moved=schedules.change(space,s.scheduleId(),actor,1,new ScheduleStore.Input("Moved","",s.startsAt(),s.endsAt(),"UTC",null),false,trace);assertEquals(v,store.get(space,v.reminderId()));var fresh=input(moved,30);var next=store.change(space,v.reminderId(),actor,1,fresh,store.preview(space,fresh).previewHash(),false,trace);assertEquals(2,next.version());assertEquals(2,next.schedule().version());assertEquals(v,store.history(space,v.reminderId(),2,5).getFirst().snapshot());schedules.change(space,s.scheduleId(),actor,2,null,true,trace);var retired=store.change(space,v.reminderId(),ids.next(),2,null,null,true,trace);assertEquals("RETIRED",retired.state());assertEquals(retired,store.get(space,v.reminderId()));assertEquals(v,store.create(space,ids.next(),key,i,p.previewHash(),trace).reminder());assertEquals(actor,store.history(space,v.reminderId(),Long.MAX_VALUE,5).getLast().actorId());assertEquals(3,count("reminder_revision"));status(409,()->store.create(space,actor,key,input(s,25),p.previewHash(),trace));}
    @Test void staleSourcePreviewOrReminderVersionNeverConsumesKeyOrChangesFacts(){var s=schedule(space);var i=input(s,0);String key=key(),hash=store.preview(space,i).previewHash();status(412,()->store.create(space,actor,key,i,"a".repeat(64),trace));assertEquals(0,count("reminder"));var v=store.create(space,actor,key,i,hash,trace).reminder();assertEquals(v,store.change(space,v.reminderId(),actor,1,i,hash,false,trace));assertEquals(1,count("reminder_revision"));schedules.change(space,s.scheduleId(),actor,1,new ScheduleStore.Input("Changed","",s.startsAt(),s.endsAt(),s.timeZone(),null),false,trace);status(412,()->store.create(space,actor,key(),i,hash,trace));status(412,()->store.change(space,v.reminderId(),actor,1,i,hash,false,trace));assertEquals(1,count("reminder_revision"));status(412,()->store.change(space,v.reminderId(),actor,2,null,null,true,trace));assertEquals(v,store.get(space,v.reminderId()));}
    @Test void foreignMissingRetiredAndImmutableScheduleLinksAreDenied(){var s=schedule(space);var v=create(s,10);var foreign=schedule(ids.next());status(404,()->store.preview(space,input(foreign,10)));status(404,()->store.get(actor,v.reminderId()));status(404,()->store.history(actor,v.reminderId(),Long.MAX_VALUE,5));assertThrows(RuntimeException.class,()->sql.update("UPDATE reminder SET space_id=? WHERE reminder_id=?",actor,v.reminderId()));var other=schedule(space);var i=input(other,10);status(400,()->store.change(space,v.reminderId(),actor,1,i,store.preview(space,i).previewHash(),false,trace));schedules.change(space,s.scheduleId(),actor,1,null,true,trace);status(404,()->store.preview(space,input(s,20)));assertEquals(v,store.get(space,v.reminderId()));assertEquals("RETIRED",store.change(space,v.reminderId(),actor,1,null,null,true,trace).state());}
    @Test void outboxFailureRollsBackCreateUpdateRetirementAndKeyReservation(){var s=schedule(space);sql.execute("CREATE FUNCTION fail_reminder() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.aggregatetype='reminder' THEN RAISE EXCEPTION 'controlled reminder failure'; END IF; RETURN NEW; END $$");sql.execute("CREATE TRIGGER fail_reminder BEFORE INSERT ON outbox_event FOR EACH ROW EXECUTE FUNCTION fail_reminder()");var i=input(s,10);String key=key(),hash=store.preview(space,i).previewHash();assertThrows(RuntimeException.class,()->store.create(space,actor,key,i,hash,trace));assertEquals(0,count("reminder"));sql.execute("ALTER TABLE outbox_event DISABLE TRIGGER fail_reminder");var v=store.create(space,actor,key,i,hash,trace).reminder();sql.execute("ALTER TABLE outbox_event ENABLE TRIGGER fail_reminder");var changed=input(s,20);assertThrows(RuntimeException.class,()->store.change(space,v.reminderId(),actor,1,changed,store.preview(space,changed).previewHash(),false,trace));assertThrows(RuntimeException.class,()->store.change(space,v.reminderId(),actor,1,null,null,true,trace));assertEquals(v,store.get(space,v.reminderId()));assertEquals(1,count("reminder_revision"));assertEquals(2,count("outbox_event"));}
    @Test void concurrentIdenticalCreatesAndCompetingEditsHaveOneWinner()throws Exception{var s=schedule(space);var i=input(s,10);String key=key(),hash=store.preview(space,i).previewHash();try(var pool=Executors.newFixedThreadPool(2)){var barrier=new CyclicBarrier(2);var a=pool.submit(()->{barrier.await();return store.create(space,actor,key,i,hash,trace);});var b=pool.submit(()->{barrier.await();return store.create(space,actor,key,i,hash,trace);});var first=a.get();var second=b.get();assertEquals(first.reminder(),second.reminder());assertNotEquals(first.replay(),second.replay());var v=first.reminder();var gate=new CyclicBarrier(2);var futures=new ArrayList<Future<Integer>>();for(int offset:new int[]{20,30})futures.add(pool.submit(()->{gate.await();var changed=input(s,offset);try{store.change(space,v.reminderId(),actor,1,changed,store.preview(space,changed).previewHash(),false,trace);return 200;}catch(ResponseStatusException e){return e.getStatusCode().value();}}));assertEquals(Set.of(200,412),Set.of(futures.get(0).get(),futures.get(1).get()));assertEquals(2,count("reminder_revision"));}}
    @Test void cursorAndHistoryPagesAreBoundToSpaceStateAndSchedule(){var s=schedule(space);for(int n=0;n<23;n++)create(s,n);var a=store.list(space,"ACTIVE",s.scheduleId().toString(),null,20);var b=store.list(space,"ACTIVE",s.scheduleId().toString(),a.nextAfter(),20);assertEquals(20,a.items().size());assertEquals(3,b.items().size());assertNull(b.nextAfter());status(400,()->store.list(actor,"ACTIVE",s.scheduleId().toString(),a.nextAfter(),20));status(400,()->store.list(space,"RETIRED",s.scheduleId().toString(),a.nextAfter(),20));status(400,()->store.list(space,"ACTIVE","ALL",a.nextAfter(),20));var v=a.items().getFirst();for(int n=1;n<=6;n++){var i=input(s,100+n);v=store.change(space,v.reminderId(),actor,n,i,store.preview(space,i).previewHash(),false,trace);}var page=store.history(space,v.reminderId(),Long.MAX_VALUE,5);assertEquals(List.of(7L,6L,5L,4L,3L),page.stream().map(ReminderStore.Revision::version).toList());assertEquals(List.of(2L,1L),store.history(space,v.reminderId(),3,5).stream().map(ReminderStore.Revision::version).toList());assertEquals(s,schedules.get(space,s.scheduleId()));}
}
